// Client-side: keep one WebSocket open, retry with the same clientMsgId
const ws = new WebSocket('wss://chat.example.com');
function send(conversationId, text) {
  const clientMsgId = crypto.randomUUID(); // server dedupes retries
  ws.send(JSON.stringify({ type: 'send_message', conversationId, clientMsgId, text }));
}
ws.onmessage = (e) => {
  const evt = JSON.parse(e.data);
