// API sketch
// GET  /hotels/:id/availability?room_type=deluxe&check_in=2026-03-10&check_out=2026-03-12
// POST /reservations   headers: Idempotency-Key: <uuid>   body: { hotelId, roomType, checkIn, checkOut }
// DELETE /reservations/:id

async function createReservation(req, res, db) {
  const key = req.get('Idempotency-Key');
  if (!key) return res.status(400).json({ error: 'Idempotency-Key header required' });

  const existing = await db.oneOrNone('SELECT * FROM reservations WHERE idempotency_key = $1', [key]);
  if (existing) return res.json(existing);              // retry → same answer

  try {
    const booking = await db.tx(async (t) => {
      const days = nightsBetween(req.body.checkIn, req.body.checkOut);
      const { rowCount } = await t.result(
        `UPDATE room_inventory SET reserved = reserved + 1
          WHERE hotel_id = $1 AND room_type = $2 AND day = ANY($3) AND reserved < total`,
        [req.body.hotelId, req.body.roomType, days],
      );
      if (rowCount !== days.length) throw new Error('SOLD_OUT');   // rolls back
      return t.one('INSERT INTO reservations (...) VALUES (...) RETURNING *', [key /* , ... */]);
    });
    res.status(201).json(booking);
  } catch (e) {
    if (e.message === 'SOLD_OUT') return res.status(409).json({ error: 'Sold out for those dates' });
    throw e;
  }
}

