class SagaFailed(Exception):
    pass

class Saga:
    """Orchestrated saga: run steps in order; on failure run compensations in reverse."""
    def __init__(self):
        self.steps = []                            # (name, action, compensation)

    def step(self, name, action, compensation=None):
        self.steps.append((name, action, compensation))
        return self

    def run(self, ctx: dict) -> dict:
        done = []
        for name, action, compensation in self.steps:
            try:
                action(ctx)
                done.append((name, compensation))
            except Exception as e:
                for prev, undo in reversed(done):
                    if undo:
                        undo(ctx)                  # must be idempotent and retried until it succeeds
                raise SagaFailed(f'{name} failed: {e}') from e
        return ctx

# --- fake services ---
stock = {'headphones': 5}
orders = {}

def create_order(c): orders[c['id']] = 'PENDING'
def cancel_order(c): orders[c['id']] = 'CANCELLED'
def reserve(c):
    if stock[c['sku']] < c['qty']:
        raise ValueError('out of stock')
    stock[c['sku']] -= c['qty']
def release(c): stock[c['sku']] += c['qty']
def charge(c):
    if c['card'] == 'declined':
        raise ValueError('card declined')
def refund(c): pass
def confirm(c): orders[c['id']] = 'CONFIRMED'

checkout = (Saga()
            .step('create order', create_order, cancel_order)
            .step('reserve stock', reserve, release)
            .step('charge payment', charge, refund)
            .step('confirm', confirm))

try:
    checkout.run({'id': 1, 'sku': 'headphones', 'qty': 2, 'card': 'declined'})
except SagaFailed as e:
    print(e, '| stock:', stock, '| order:', orders[1])   # stock back to 5, order CANCELLED

