// Outbox pattern: save the state change and the event in ONE local transaction,
// then a relay publishes outbox rows to Kafka/SQS. No lost or phantom events.
async function reserveStock(db, { orderId, sku, qty }) {
  await db.tx(async (t) => {
    const { rowCount } = await t.result(
      'UPDATE inventory SET available = available - $1, reserved = reserved + $1 WHERE sku = $2 AND available >= $1',
      [qty, sku],
    );
    const event = rowCount ? 'StockReserved' : 'StockReservationFailed';
    await t.none('INSERT INTO outbox (aggregate_id, type, payload) VALUES ($1, $2, $3)', [orderId, event, { sku, qty }]);
  });
}

// Relay (runs in a loop or uses CDC like Debezium)
async function relayOutbox(db, broker) {
  const rows = await db.any('SELECT * FROM outbox WHERE published_at IS NULL ORDER BY id LIMIT 100');
  for (const row of rows) {
    await broker.publish(row.type, { id: row.id, ...row.payload }); // consumers dedupe by id
    await db.none('UPDATE outbox SET published_at = now() WHERE id = $1', [row.id]);
  }
}

