import math

BASE32 = '0123456789bcdefghjkmnpqrstuvwxyz'

def geohash(lat: float, lng: float, precision: int = 6) -> str:
    lat_rng, lng_rng = [-90.0, 90.0], [-180.0, 180.0]
    out, bits, ch, even = [], 0, 0, True        # even bit → longitude
    while len(out) < precision:
        rng, val = (lng_rng, lng) if even else (lat_rng, lat)
        mid = (rng[0] + rng[1]) / 2
        if val >= mid:
            ch = (ch << 1) | 1; rng[0] = mid
        else:
            ch <<= 1; rng[1] = mid
        even, bits = not even, bits + 1
        if bits == 5:
            out.append(BASE32[ch]); bits, ch = 0, 0
    return ''.join(out)

def cell_size(precision: int) -> tuple[float, float]:
    total = 5 * precision
    lng_bits, lat_bits = (total + 1) // 2, total // 2
    return 180 / 2 ** lat_bits, 360 / 2 ** lng_bits   # degrees (lat, lng)

def nine_cells(lat, lng, precision):
    dlat, dlng = cell_size(precision)
    return {geohash(max(-90, min(90, lat + i * dlat)), lng + j * dlng, precision)
            for i in (-1, 0, 1) for j in (-1, 0, 1)}

def haversine_km(a, b):
    (lat1, lng1), (lat2, lng2) = map(lambda p: map(math.radians, p), (a, b))
    h = math.sin((lat2 - lat1) / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin((lng2 - lng1) / 2) ** 2
    return 2 * 6371 * math.asin(math.sqrt(h))

# index: geohash(6) -> [(name, lat, lng)]  (Redis / a DB index in real life)
places = [('Dosa Point', 12.9720, 77.5950), ('Cafe 77', 12.9750, 77.6000), ('Far Away Mess', 13.0500, 77.7000)]
index = {}
for p in places:
    index.setdefault(geohash(p[1], p[2]), []).append(p)

def nearby(lat, lng, radius_km=1.0, precision=6):
    candidates = [p for cell in nine_cells(lat, lng, precision) for p in index.get(cell, [])]
    hits = [(round(haversine_km((lat, lng), p[1:]), 2), p[0]) for p in candidates]
    return sorted(h for h in hits if h[0] <= radius_km)

print(geohash(57.64911, 10.40744, 11))   # 'u4pruydqqvj' (standard test value)
print(nearby(12.9716, 77.5946))          # Dosa Point and Cafe 77, not Far Away Mess

