class Codec {
  constructor() {
    this.codeToUrl = new Map();
    this.urlToCode = new Map();
    this.chars = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  }
  encode(longUrl) {
    if (this.urlToCode.has(longUrl)) return 'http://tinyurl.com/' + this.urlToCode.get(longUrl);
    let code = Array.from({length: 6}, () => this.chars[Math.floor(Math.random() * 62)]).join('');
    this.codeToUrl.set(code, longUrl);
    this.urlToCode.set(longUrl, code);
    return 'http://tinyurl.com/' + code;
  }
}

